{
  "name": "GSV-3USB传感器测量放大器",
  "name_en": "GSV-3USB Sensor Measurement Amplifier",
  "manufacturer": "",
  "description": "这是一种通过 USB 连接的传感器测量放大器/信号调理设备，常用于连接应变片式力传感器、称重传感器等，将传感器输出转换为可读取的数字测量值。在实验室中可用于力、重量或相关模拟信号的采集，并支持清零、偏置、量程极性与连续数据传输等操作。",
  "description_en": "This is a USB-connected sensor measurement amplifier and signal-conditioning unit, typically used with strain-gauge force sensors, load cells, and similar transducers. It converts sensor output into readable digital measurements for laboratory force, weight, or related analog-signal acquisition, and supports zeroing, offset adjustment, polarity/range selection, and continuous data transmission.",
  "tag_hints": [
    "USB measurement amplifier",
    "signal conditioning",
    "load cell measurement",
    "force measurement",
    "strain gauge sensor",
    "data streaming",
    "zero offset calibration"
  ],
  "actions": [
    {
      "action_name": "auto-get_all",
      "description": "读取设备指定配置档中的全部参数。",
      "description_en": "Read all parameters from the selected device profile."
    },
    {
      "action_name": "auto-save_all",
      "description": "将当前全部设置保存到设备配置档。",
      "description_en": "Save all current settings to a device profile."
    },
    {
      "action_name": "auto-start_transmission",
      "description": "开始连续传输测量数据。",
      "description_en": "Start continuous transmission of measurement data."
    },
    {
      "action_name": "auto-stop_transmission",
      "description": "停止连续传输测量数据。",
      "description_en": "Stop continuous transmission of measurement data."
    },
    {
      "action_name": "auto-set_zero",
      "description": "将当前输入设为零点。",
      "description_en": "Set the current input as the zero point."
    },
    {
      "action_name": "auto-set_offset",
      "description": "设置测量偏置补偿。",
      "description_en": "Set measurement offset compensation."
    },
    {
      "action_name": "auto-set_bipolar",
      "description": "将测量模式设为双极性。",
      "description_en": "Set the measurement mode to bipolar."
    },
    {
      "action_name": "auto-set_unipolar",
      "description": "将测量模式设为单极性。",
      "description_en": "Set the measurement mode to unipolar."
    },
    {
      "action_name": "auto-get_serial_nr",
      "description": "读取设备序列号。",
      "description_en": "Read the device serial number."
    },
    {
      "action_name": "auto-set_mode",
      "description": "设置数据输出模式。",
      "description_en": "Set the data output mode."
    },
    {
      "action_name": "auto-get_mode",
      "description": "读取数据输出模式。",
      "description_en": "Read the data output mode."
    },
    {
      "action_name": "auto-get_firmware_version",
      "description": "读取设备固件版本。",
      "description_en": "Read the device firmware version."
    },
    {
      "action_name": "auto-get_special_mode",
      "description": "读取特殊工作模式。",
      "description_en": "Read the special operating mode."
    },
    {
      "action_name": "auto-set_special_mode",
      "description": "设置特殊工作模式。",
      "description_en": "Set the special operating mode."
    },
    {
      "action_name": "auto-read_value",
      "description": "读取当前测量值。",
      "description_en": "Read the current measured value."
    },
    {
      "action_name": "auto-clear_maximum",
      "description": "清除记录的最大值。",
      "description_en": "Clear the stored maximum value."
    },
    {
      "action_name": "auto-clear_buffer",
      "description": "清空设备数据缓冲区。",
      "description_en": "Clear the device data buffer."
    },
    {
      "action_name": "auto-convertValue",
      "description": "将原始测量值换算为对应的工程单位数值。",
      "description_en": "Convert a raw measurement value into the corresponding engineering-unit value."
    }
  ]
}

